const express = require('express');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const argon2 = require('argon2');

const app = express();
app.use(express.json());

// Secure session store
const sessions = new Map();
const STATIC_ROOT = path.resolve('/var/www/static');

// Rate limiting
const rateLimiter = new Map();
function checkRate(ip) {
  const now = Date.now();
  const entry = rateLimiter.get(ip) || { count: 0, reset: now + 60000 };
  if (now > entry.reset) { entry.count = 0; entry.reset = now + 60000; }
  entry.count++;
  rateLimiter.set(ip, entry);
  return entry.count <= 100;
}

// Auth middleware
async function authenticate(req, res, next) {
  const sessionId = req.headers['x-session-id'];
  if (!sessionId || typeof sessionId !== 'string') return res.status(401).json({ error: 'Unauthorized' });
  const session = sessions.get(sessionId);
  if (!session || session.expires < Date.now()) {
    sessions.delete(sessionId);
    return res.status(401).json({ error: 'Session expired' });
  }
  req.user = session.user;
  next();
}

// Normalize path to prevent traversal
function normalizePath(userPath) {
  // Decode percent-encoded characters once only
  let decoded = decodeURIComponent(userPath);
  // Remove null bytes
  decoded = decoded.replace(/\0/g, '');
  // Normalize the path
  const normalized = path.normalize(decoded);
  return normalized;
}

// Validate that resolved path is within root
function isWithinRoot(filePath, root) {
  const resolved = path.resolve(root, filePath);
  // Check that the resolved path starts with root
  return resolved.startsWith(root + path.sep) || resolved === root;
}

// Static file serving endpoint
app.get('/files/:category/*', authenticate, (req, res) => {
  if (!checkRate(req.ip)) return res.status(429).json({ error: 'Rate limited' });

  const category = req.params.category;
  // Whitelist categories
  const allowedCategories = ['docs', 'images', 'templates', 'public'];
  if (!allowedCategories.includes(category)) {
    return res.status(400).json({ error: 'Invalid category' });
  }

  // Get the file path from wildcard
  const rawPath = req.params[0];
  if (!rawPath || typeof rawPath !== 'string' || rawPath.length > 255) {
    return res.status(400).json({ error: 'Invalid path' });
  }

  // Normalize and validate
  const normalizedFile = normalizePath(rawPath);
  const categoryRoot = path.join(STATIC_ROOT, category);

  // Security check: ensure file is within category directory
  if (!isWithinRoot(normalizedFile, categoryRoot)) {
    return res.status(403).json({ error: 'Access denied' });
  }

  const fullPath = path.resolve(categoryRoot, normalizedFile);

  // Double-check after resolution
  if (!fullPath.startsWith(categoryRoot + path.sep) && fullPath !== categoryRoot) {
    return res.status(403).json({ error: 'Access denied' });
  }

  // Additional extension whitelist
  const allowedExts = ['.html', '.css', '.js', '.png', '.jpg', '.svg', '.pdf', '.txt'];
  const ext = path.extname(fullPath).toLowerCase();
  if (!allowedExts.includes(ext)) {
    return res.status(403).json({ error: 'File type not allowed' });
  }

  fs.stat(fullPath, (err, stats) => {
    if (err || !stats.isFile()) return res.status(404).json({ error: 'Not found' });
    if (stats.size > 10 * 1024 * 1024) return res.status(413).json({ error: 'File too large' });
    res.sendFile(fullPath);
  });
});

// Template rendering with variable substitution
app.post('/render', authenticate, (req, res) => {
  if (!checkRate(req.ip)) return res.status(429).json({ error: 'Rate limited' });

  const { template_name, variables } = req.body;
  if (!template_name || typeof template_name !== 'string') {
    return res.status(400).json({ error: 'Invalid template name' });
  }
  if (!/^[a-zA-Z0-9_-]+$/.test(template_name)) {
    return res.status(400).json({ error: 'Invalid template name format' });
  }

  const templatePath = path.join(STATIC_ROOT, 'templates', template_name + '.html');

  fs.readFile(templatePath, 'utf-8', (err, content) => {
    if (err) return res.status(404).json({ error: 'Template not found' });

    // Safe variable substitution - only replace {{varname}} patterns
    if (variables && typeof variables === 'object' && !Array.isArray(variables)) {
      const safeVars = Object.create(null);
      for (const [key, val] of Object.entries(variables)) {
        if (/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(key) && typeof val === 'string') {
          safeVars[key] = val.replace(/[<>&"']/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&#x27;'}[c]));
        }
      }
      content = content.replace(/\{\{([a-zA-Z_][a-zA-Z0-9_]*)\}\}/g, (match, name) => {
        return safeVars[name] !== undefined ? safeVars[name] : match;
      });
    }

    res.type('html').send(content);
  });
});

app.listen(3000);
module.exports = app;
